package md.utm.messaging.broker; import md.utm.messaging.contracts.MessageEnvelope; import java.util.concurrent.*; import java.util.*;
public final class BrokerStorage { private final ConcurrentMap<String,BlockingQueue<MessageEnvelope>> queues=new ConcurrentHashMap<>(); private final ConcurrentLinkedQueue<DeadLetter> dlq=new ConcurrentLinkedQueue<>(); public BlockingQueue<MessageEnvelope> queue(String d){return queues.computeIfAbsent(d,k->new LinkedBlockingQueue<>());} public void deadLetter(DeadLetter d){dlq.add(d);} public List<DeadLetter> deadLetters(){return List.copyOf(dlq);} }
